"import json\nimport os\n\npath = r\"C:\\Users\\a-6600\\.gemini\\antigravity\\brain\\defefd3d-03a6-48cc-ab0b-1fbc66f83de5\\.system_generated\\logs\\transcript.jsonl\"\nif not os.path.exists(path):\n    print(\"Transcript not found at\", path)\n    exit(1)\n\nwith open(path, \"r\", encoding=\"utf-8\") as f:\n    for idx, line in enumerate(f):\n        # Ignore tool calls that are just running python search scripts\n        if \"find_sql\" in line or \"Select-String\" in line:\n            continue\n        if \"CREATE TABLE public.fin_customers\" in line:\n            obj = json.loads(line)\n            content = obj.get(\"content\", \"\")\n            if content and \"CREATE TABLE public.fin_customers\" in content:\n                print(f\"Match found in content of line {idx}\")\n                # Save to a file named match_<idx>.sql\n                with open(f\"match_{idx}.sql\", \"w\", encoding=\"utf-8\") as sf:\n                    sf.write(content)\n            for tc in obj.get(\"tool_calls\", []):\n                args = tc.get(\"args\", {})\n                code = args.get(\"CodeContent\") or args.get(\"ReplacementContent\")\n                if code and \"CREATE TABLE public.fin_customers\" in code:\n                    print(f\"Match found in tool_call args of line {idx}\")\n                    with open(f\"match_tc_{idx}.sql\", \"w\", encoding=\"utf-8\") as sf:\n                        sf.write(code)\n"